from common import *
def run():
    bio = [
     mcq("Cells of the pancreas secrete large amounts of digestive enzymes (proteins). Which pair of cell organelles will be especially abundant in these cells?", ["Rough ER and Golgi apparatus", "Smooth ER and lysosomes", "Plastids and vacuoles", "Centrosome and chloroplasts"], 'a', "Proteins are made on ribosomes of RER and packaged/secreted by the Golgi apparatus."),
     mcq("Dry raisins are soaked in pure water for some hours and they swell. This is because water:", ["moves out of the raisin by osmosis", "moves into the raisin through its semi-permeable membrane, since water is more concentrated outside", "moves into the raisin because sugar moves out by osmosis", "moves in both directions equally"], 'b', "Osmosis: net movement of water from higher water concentration (pure water) to lower (raisin) across a semi-permeable membrane."),
     mcq("Grass grows back quickly after it is mown. This is mainly due to the activity of:", ["apical meristem at the stem tip", "lateral meristem", "intercalary meristem at the base of leaves", "cambium of the root"], 'c', "Intercalary meristem lies at the base of leaves/internodes and gives regrowth after cutting."),
     mcq("Which of the following statements about cardiac muscle is INCORRECT?", ["Its action is involuntary.", "Its cells are cylindrical and branched.", "Its cells show light and dark striations.", "Its cells are long, unbranched and multinucleate."], 'd', "Long, unbranched, multinucleate cells are characteristic of skeletal (striated) muscle, not cardiac muscle."),
     mcq(f"A solar panel of area 4 m{S(2)} receives sunlight of insolation 0.8 kW m{S('−2')} for 5 hours. The solar energy received by the panel is:", ["3.2 kWh", "16 kWh", "4 kWh", "20 kWh"], 'b', "Energy = 0.8 × 4 × 5 = 16 kWh."),
     mcq("A single-celled organism has no membrane-bound nucleus or organelles but has a cell wall. It is placed in the kingdom:", ["Protista", "Fungi", "Monera", "Plantae"], 'c', "Prokaryotes (bacteria) belong to kingdom Monera."),
     mcq("Sugarcane is propagated by planting pieces of its stem. This method of reproduction is called:", ["sexual reproduction", "vegetative propagation", "budding", "spore formation"], 'b', "New plants arise from vegetative parts (stem cuttings) – asexual vegetative propagation."),
     ar("Plasmolysis occurs when a plant cell is placed in a hypertonic solution.", "Water moves out of the cell by osmosis and the protoplast shrinks away from the cell wall.", 'a', "Hypertonic outside → water leaves the cell → protoplast shrinks; R correctly explains A."),
     ar("Ozone depletion allows more ultraviolet radiation to reach the Earth’s surface.", "Ozone is formed only in the troposphere, close to the ground.", 'c', "A is true. R is false: most ozone is in the stratosphere (the ozone layer)."),
     OR(sa("Define budding. Name one organism that reproduces by budding.", 2, "Budding: a small outgrowth (bud) develops on the parent body, grows, and detaches to become a new individual. [1] Example: <i>Hydra</i> / yeast. [1]"),
        sa("What is fragmentation? Give one example.", 2, "Breaking of the body into fragments, each of which grows into a complete new individual. [1] Example: <i>Spirogyra</i>. [1]")),
     OR(sa("Name the type of tissue present in: (i) the hard shell of a walnut, (ii) the pulp of a ripe tomato, (iii) the lining of kidney tubules.", 3, "(i) Sclerenchyma [1] (ii) Parenchyma [1] (iii) Cuboidal epithelium [1]"),
        sa("Name the muscle tissue found in: (i) the wall of the alimentary canal, (ii) the heart, (iii) the biceps attached to the bone. State one feature of each.", 3, "(i) Smooth (unstriated) – spindle-shaped, involuntary [1] (ii) Cardiac – branched, striated, involuntary [1] (iii) Skeletal – long, striated, multinucleate, voluntary [1]")),
     sa("The figure shows an animal cell with three labelled parts A, B and C. Identify each and write one function of each.", 3, "A – Nucleus: controls cell activities/stores DNA. [1] B – Mitochondrion: releases energy as ATP (powerhouse). [1] C – Golgi apparatus: modifies, packages and dispatches materials. [1]", fig=cell_fig({'nucleus': 'A', 'mito': 'B', 'golgi': 'C'})),
     sa("Copy and complete the table by writing ‘Present’ or ‘Absent’ for each cell:" + table(['Structure', 'Human cheek cell', 'Spinach leaf cell', 'Bacterium'], [['Cell wall', '', '', ''], ['Membrane-bound nucleus', '', '', ''], ['Chloroplast', '', '', '']]), 3, "Cell wall: Absent, Present, Present [1]; Membrane-bound nucleus: Present, Present, Absent [1]; Chloroplast: Absent, Present, Absent [1]"),
     sa("The figure shows a nerve cell (neuron) with parts P, Q and R labelled. Name P, Q and R and state in which direction the nerve impulse travels through the neuron.", 3, "P – Dendrites (receive impulse); Q – Cell body/cyton; R – Axon (conducts impulse away from the cell body). [½ each name + function = 2] Impulse travels dendrites → cell body → axon → nerve endings. [1]", fig=neuron_fig({'dendrite': 'P', 'body': 'Q', 'axon': 'R'})),
     case("A forest research station studied how carbon moves in nature. Students drew the cycle shown below. They noted that the amount of CO" + B(2) + " in the air has been rising since the burning of coal and petroleum increased, and that large areas of forest are being cleared for roads and farms.",
          [sub("Name the process by which green plants remove CO" + B(2) + " from the atmosphere.", 1, "Photosynthesis. [1]"),
           sub("Name one human activity, other than deforestation, that increases atmospheric CO" + B(2) + ".", 1, "Burning of fossil fuels (coal/petroleum) / vehicular emissions / industries. [1]"),
           OR(sub("Explain how deforestation can intensify the greenhouse effect.", 2, "Fewer trees → less CO" + B(2) + " removed by photosynthesis [1]; burning/decay of cut trees releases stored carbon as CO" + B(2) + " → more heat trapped. [1]"),
              sub("What is the greenhouse effect? Why is its enhancement harmful?", 2, "Natural trapping of outgoing infrared heat by gases like CO" + B(2) + ", CH" + B(4) + ", water vapour keeps Earth warm. [1] Excess gases trap more heat → global warming, melting ice, climate change. [1]"))],
          fig=cycle_fig(['Atmosphere CO₂', 'Plants', 'Animals', 'Fossil fuels']), lab='alpha'),
     OR(sa("(i) What are lysosomes? Why are they called ‘suicide bags’ of the cell?<br>(ii) State any three differences between prokaryotic and eukaryotic cells.", 5, "(i) Membrane-bound sacs of digestive enzymes [1]; on cell damage/ageing they burst and the enzymes digest the cell itself [1]. (ii) Any 3: nucleus (no true nucleus/true nucleus), nuclear membrane, membrane-bound organelles, DNA arrangement, size, example [3 × 1]"),
        sa("Study the diagram of a flower. (i) Identify parts P, Q, R and S. (ii) Name the process by which pollen reaches the stigma. (iii) What do the ovule and the ovary develop into after fertilisation?", 5, "(i) P – Stigma, Q – Style, R – Ovary, S – Ovule [4 × ½ = 2] (ii) Pollination [1] (iii) Ovule → seed [1]; ovary → fruit [1]", fig=flower_fig({'stigma': 'P', 'style': 'Q', 'ovary': 'R', 'ovule': 'S'}))),
    ]
    chem = [
     mcq("A beam of light is passed through four liquids kept in transparent beakers. The path of the beam will be clearly visible in:", ["a salt solution", "a glucose solution", "a starch solution", "a copper sulphate solution"], 'c', "Starch solution is a colloid – its particles scatter light (Tyndall effect)."),
     mcq("Whether water is obtained from a river, a well or by burning hydrogen in oxygen, hydrogen and oxygen are always found in the mass ratio 1 : 8. This illustrates the law of:", ["conservation of mass", "constant proportions", "gaseous volumes", "radioactive decay"], 'b', "Constant proportions: a pure compound always has elements in a fixed mass ratio."),
     mcq("An ion has 13 protons and 10 electrons. It is represented as:", [f"Al{S('3+')}", f"Al{S('+')}", f"Na{S('+')}", f"Mg{S('2+')}"], 'a', "Charge = +13 − 10 = +3; the element with Z = 13 is aluminium."),
     ar("Isotopes of chlorine, <sup>35</sup>Cl and <sup>37</sup>Cl, have identical chemical properties.", "Isotopes of an element have different numbers of protons.", 'c', "A is true (same electrons). R is false: isotopes have the same number of protons but different numbers of neutrons."),
     sa("The thickness of a hair is 0.00008 m. Express it (i) in scientific notation and (ii) in micrometres (1 µm = 10<sup>−6</sup> m).", 2, f"(i) 8 × 10{S('−5')} m [1] (ii) 8 × 10{S('−5')} ÷ 10{S('−6')} = 80 µm [1]"),
     sa("Name the technique used to separate (i) the different dyes present in black ink and (ii) cream from milk. State the principle behind each.", 2, "(i) Chromatography – different solubility/adsorption of dyes in the solvent [1] (ii) Centrifugation – difference in density when spun [1]"),
     sa("Calculate the molecular mass of carbon dioxide (C = 12 u, O = 16 u) and the ratio by mass of carbon to oxygen in it.", 2, "CO₂ = 12 + 2 × 16 = 44 u [1]; C : O = 12 : 32 = 3 : 8 [1]"),
     sa("A saline solution is prepared by dissolving 18 g of sodium chloride in 282 g of water. (i) Calculate the mass percentage (% m/m) of the solution. (ii) How much sodium chloride is present in 500 g of this solution?", 3, "(i) Mass of solution = 18 + 282 = 300 g [½]; % m/m = (18/300) × 100 = 6 % [1½] (ii) 6 % of 500 g = 30 g [1]"),
     OR(sa("State any three postulates of Bohr’s model of the atom.", 3, "(i) Electrons revolve in fixed circular orbits (shells) without radiating energy. (ii) Each orbit has a fixed energy; K, L, M… (iii) Energy is absorbed/emitted only when an electron jumps between orbits. (iv) Maximum electrons 2n². [Any 3 × 1]"),
        sa("Differentiate between isotopes and isobars with one example of each.", 3, "Isotopes: same atomic number, different mass number (e.g. <sup>12</sup>C, <sup>14</sup>C) [1½]. Isobars: same mass number, different atomic number (e.g. <sup>40</sup>Ar, <sup>40</sup>Ca) [1½].")),
     case("A teacher tested three unlabelled samples P, Q and R, and recorded the observations in the table.<br>" + table(['Sample', 'Appearance', 'Light path visible?', 'Settles on standing?', 'Residue on filter paper?'], [['P', 'Clear', 'No', 'No', 'No'], ['Q', 'Cloudy', 'Yes', 'Yes', 'Yes'], ['R', 'Translucent', 'Yes', 'No', 'No']]),
          [sub("Classify the samples P, Q and R as solution, suspension or colloid.", 1, "P – solution; Q – suspension; R – colloid. [1]"),
           sub("Why can sample R not be separated by ordinary filtration even though it is not a true solution?", 1, "Colloidal particles are very small (1–100 nm) and pass through filter paper. [1]"),
           OR(sub("Name the process to obtain the dissolved solute from sample P and write one example of sample P.", 2, "Evaporation/crystallisation [1]; example – salt/sugar solution [1]"),
              sub("Arrange P, Q and R in increasing order of particle size and justify using the observations.", 2, "P < R < Q [1]; P shows no scattering and passes through filter; R scatters but passes filter; Q scatters, settles and is retained. [1]"))], lab='alpha'),
     OR(sa("A mixture contains common salt, sand and iron filings. Describe, step by step, how you will separate the three components, naming the principle used at each step.", 5, "1. Magnet removes iron filings (magnetic property) [1½] 2. Add water, stir – salt dissolves, sand does not [1] 3. Filter – sand is the residue [1] 4. Evaporate/crystallise the filtrate – salt obtained [1½]"),
        sa("The chromatogram of a dye mixture is shown (solvent front is 100 mm above the baseline). (a) State the principle of paper chromatography. (b) Find the R<sub>f</sub> value of spots A, B and C. (c) Which component is the most soluble in the solvent?", 5, "(a) Components of a mixture move with the solvent at different rates according to their solubility in the solvent and adsorption on paper. [2] (b) R<sub>f</sub> = distance moved by spot ÷ distance moved by solvent: A = 30/100 = 0.30; B = 55/100 = 0.55; C = 80/100 = 0.80 [2] (c) C – it travelled farthest. [1]", fig=chromatogram({'A': 30, 'B': 55, 'C': 80}))),
    ]
    phy = [
     mcq("A runner completes one full lap of a 400 m circular track in 80 s. Her average speed and average velocity for the lap are respectively:", ["5 m s<sup>−1</sup>, 0", "0, 5 m s<sup>−1</sup>", "5 m s<sup>−1</sup>, 5 m s<sup>−1</sup>", "0, 0"], 'a', "Average speed = 400/80 = 5 m s⁻¹; displacement is zero, so average velocity is zero."),
     mcq("The velocity–time graph of a car is shown. The distance covered by the car in the first 10 s is:", ["50 m", "75 m", "100 m", "125 m"], 'b', "Area = ½ × 5 × 10 + 5 × 10 = 25 + 50 = 75 m.", fig=graph([(0, 0), (5, 10), (10, 10), (15, 0)], 15, 12, 't (s)', 'v (m s⁻¹)', 5, 2)),
     mcq("The figure shows the horizontal forces acting on a 4 kg block on a smooth surface. Its acceleration is:", ["5 m s<sup>−2</sup>", "2 m s<sup>−2</sup>", "0.5 m s<sup>−2</sup>", "8 m s<sup>−2</sup>"], 'b', "Net force = 14 − 6 = 8 N; a = F/m = 8/4 = 2 m s⁻².", fig=force_fig('4 kg', left=('6 N', 45), right=('14 N', 80))),
     mcq("A rocket moves upward by throwing hot gases downward. This is an example of Newton’s:", ["first law", "second law", "third law", "law of gravitation"], 'c', "Action (gases pushed down) and reaction (rocket pushed up) – third law."),
     mcq("A 2 kg body is raised through a height of 5 m. The work done against gravity is (g = 10 m s<sup>−2</sup>):", ["10 J", "50 J", "100 J", "20 J"], 'c', "W = mgh = 2 × 10 × 5 = 100 J."),
     mcq("A sound wave has a frequency of 250 Hz and a wavelength of 1.36 m. The speed of the wave is:", ["183.8 m s<sup>−1</sup>", "1.36 m s<sup>−1</sup>", "250 m s<sup>−1</sup>", "340 m s<sup>−1</sup>"], 'd', "v = fλ = 250 × 1.36 = 340 m s⁻¹."),
     ar("A force can change the direction of a moving body.", "A force can change the speed of a body.", 'b', "Both statements are true, but changing speed does not explain changing direction."),
     sa("A car moving at 10 m s<sup>−1</sup> accelerates uniformly at 2 m s<sup>−2</sup> for 5 s. Find (i) its final velocity and (ii) the distance covered in this time.", 2, "(i) v = u + at = 10 + 2×5 = 20 m s⁻¹ [1] (ii) s = ut + ½at² = 10×5 + ½×2×25 = 75 m [1]"),
     OR(sa("A cyclist stops pedalling but the bicycle keeps moving for some distance. Name the law that explains this and state why the cycle finally stops.", 2, "Newton’s first law (inertia) [1]; friction/air resistance (unbalanced force) slows it. [1]"),
        sa("A gun recoils backward when a bullet is fired. Name the law that explains this and state why the recoil velocity is much smaller than the velocity of the bullet.", 2, "Newton’s third law/conservation of momentum [1]; gun has a much larger mass than the bullet. [1]")),
     sa("A pump raises 600 kg of water to a height of 20 m in 2 minutes. Calculate (i) the work done and (ii) the power of the pump (g = 10 m s<sup>−2</sup>).", 3, "(i) W = mgh = 600 × 10 × 20 = 1,20,000 J [1½] (ii) P = W/t = 120000/120 = 1000 W [1½]"),
     case("During a hockey match, Seema, the goalkeeper, stops a ball of mass 0.16 kg moving at 25 m s<sup>−1</sup>. The ball comes to rest in 0.05 s when she stops it with her padded gloves.",
          [sub("Calculate the momentum of the ball before it is stopped.", 1, "p = mv = 0.16 × 25 = 4 kg m s⁻¹. [1]"),
           sub("Find the average force exerted by the ball on her gloves.", 1, "F = Δp/t = 4/0.05 = 80 N. [1]"),
           OR(sub("Why do goalkeepers pull their hands backward while stopping a fast ball?", 2, "Increases the time of stopping [1]; so rate of change of momentum (force) decreases and injury is avoided. [1]"),
              sub("If the ball were stopped in 0.2 s instead, what force would be exerted? Compare it with the first case.", 2, "F = 4/0.2 = 20 N [1]; it is 4 times smaller than 80 N since time is 4 times longer. [1]"))], lab='alpha'),
     OR(sa("A cyclist rides 6 km east in 20 minutes and then 8 km north in the next 20 minutes. Calculate (i) the total distance covered, (ii) the magnitude of displacement, (iii) the average speed and (iv) the average velocity. Why is the average speed greater than the average velocity?", 5, "(i) 14 km [1] (ii) √(6²+8²) = 10 km [1] (iii) 14 ÷ (40/60) = 21 km h⁻¹ [1] (iv) 10 ÷ (2/3) = 15 km h⁻¹ [1] Because distance (path length) is greater than displacement. [1]"),
        sa("A body starts from rest, accelerates uniformly at 2 m s<sup>−2</sup> for 10 s, moves with constant velocity for the next 20 s and then comes to rest uniformly in 5 s. Find (i) the maximum velocity, (ii) the distance in the first 10 s, (iii) the distance at constant velocity, (iv) the retardation and (v) the total distance.", 5, "(i) 20 m s⁻¹ [1] (ii) ½×2×100 = 100 m [1] (iii) 20×20 = 400 m [1] (iv) 20/5 = 4 m s⁻² [1] (v) 100 + 400 + ½×20×5 (=50) = 550 m [1]")),
    ]
    science_paper(1, bio, chem, phy)
if __name__ == '__main__': run()
